def promedio_ponderado(notas, pesos):
    """Devuelve el promedio de notas según sus pesos."""
    if len(notas) != len(pesos):
        raise ValueError("Cada nota necesita un peso")
    total = sum(n * p for n, p in zip(notas, pesos))
    return total / sum(pesos)


print(promedio_ponderado([4.0, 3.5, 5.0], [0.3, 0.3, 0.4]))
